import sys

mod = 998244353

def compute_fn(x, y, st, type_, cache):
    if st in cache[type_]:
        return cache[type_][st]
    if st == 1:
        return x if type_ == 0 else y
    if st % 2 == 1:
        res = (x * compute_fn(x, y, st - 1, type_, cache) + y * compute_fn(x, y, st - 1, (type_ + 1) % 2, cache)) % mod
        return res
    else:
        half = st // 2
        ch = compute_fn(x, y, half, 0, cache)
        nch = compute_fn(x, y, half, 1, cache)
        if type_ == 0:
            ans = (ch * ch + nch * nch) % mod
        else:
            ans = (2 * ch * nch) % mod
        cache[type_][st] = ans
        return ans

def compute_bin(x, st):
    if st == 0:
        return 1
    if st == 1:
        return x
    m = st // 2
    res = compute_bin(x, m)
    if st % 2 == 0:
        return (res * res) % mod
    else:
        return ((res * res) % mod * x) % mod

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    p = int(input_data[2])
    q = int(input_data[3])
