    if p % 2 == 0:
        x = x - x // 2
    else:
        x //= 2
    y = q - p + 1 - x
    cache = [dict(), dict()]
    if ((n & m) % 2) == 0:
        result = compute_fn(x, y, n * m, 0, cache)
        print(result)
    else:
        result = compute_bin(x + y, n * m)
        print(result)

if __name__ == "__main__":
    main()

